/**
 * security-contract-test-static.cjs — CI-safe security contract (REM-INV-5)
 *
 * Faithful, secret-free reproduction of scripts/security-contract-test.cjs
 * (the LIVE contract, which requires SUPABASE_ACCESS_TOKEN and therefore MUST
 * NOT run in CI). Two layers, same 4 checks + same REM-INV-2R pin + same
 * severity→exit mapping:
 *
 *   Layer A — CERTIFIED LIVE SURFACE:
 *     replays supabase/security-contract/contract-surface.sql (generated by
 *     scripts/export-contract-surface.cjs from LIVE via Management API; 134
 *     SECURITY DEFINER write functions at certification time) applying checks
 *     1-4 against the verbatim function definitions and their captured proacl.
 *     Any CRITICAL/HIGH violation here = contract failure (exit 1).
 *
 *   Layer B — MIGRATION STREAM (PR surface):
 *     replays supabase/migrations/*.sql in filename order and applies the same
 *     checks to the final state of every function defined there. Historical
 *     definitions that pre-date the out-of-band LIVE fixes are accepted ONLY
 *     through the reviewed baseline in ci-gate-allowlist.json
 *     (security_contract_static_baseline: function + expected rules + reason +
 *      added_by + expires — same convention as security_definer_without_auth_check).
 *     A NEW rule violation on any function (allowlisted or not) blocks (exit 1).
 *
 * Checks (identical regexes to the LIVE contract):
 *   1. ANTI_SPOOFING_GUARD_MISSING (CRITICAL)
 *   2. VULNERABLE_PATTERN_IS_NOT_NULL_AND_NOT / _THEN (HIGH)
 *   3. ANON_EXECUTE_GRANTED (MEDIUM; webhook exception applies)
 *   4. SEARCH_PATH_NOT_SET (LOW)
 *   + RETIRED_V1_FUNCTION_REINTRODUCED pin (CRITICAL) on both layers
 *
 * Exit codes: 0 = pass (MEDIUM/LOW warnings allowed, as in the LIVE contract),
 * 1 = blocking violation, 2 = harness/infrastructure error.
 *
 * Usage: node scripts/security-contract-test-static.cjs
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const REPO = path.join(__dirname, '..');
const MIGRATIONS_DIR = path.join(REPO, 'supabase', 'migrations');
const SURFACE_FILE = path.join(REPO, 'supabase', 'security-contract', 'contract-surface.sql');
const ALLOWLIST_FILE = path.join(REPO, 'ci-gate-allowlist.json');

const WRITE_RE = /(INSERT|UPDATE|DELETE)\s+(INTO|public\.)/is;

function checkFunction(def, name, aclAnonFlag) {
  const issues = [];
  // ─── Check 1: Anti-spoofing guard V2.12.9 (identical to LIVE) ───
  const hasPUserId = /p_user_id\s+uuid/i.test(def);
  const hasStoreAccessAs = /public\.has_store_access_as/i.test(def);
  const hasSpoofingGuard = /auth\.role\(\)\s*=\s*'service_role'/i.test(def);
  if (hasPUserId && hasStoreAccessAs && !hasSpoofingGuard) {
    issues.push({ severity: 'CRITICAL', rule: 'ANTI_SPOOFING_GUARD_MISSING', msg: 'Función acepta p_user_id + usa has_store_access_as pero NO tiene CASE auth.role() = service_role guard' });
  }
  // ─── Check 2: vulnerable patterns (identical to LIVE) ───
  if (/(v_caller_uid|v_uid|v_user_id)\s+IS\s+NOT\s+NULL\s+AND\s+NOT\s+public\.has_store_access_as/is.test(def)) {
    issues.push({ severity: 'HIGH', rule: 'VULNERABLE_PATTERN_IS_NOT_NULL_AND_NOT', msg: 'Patrón vulnerable fail-open: IS NOT NULL AND NOT has_store_access_as' });
  }
  if (/(v_caller_uid|v_uid)\s+IS\s+NOT\s+NULL\s+THEN\s*\n\s*IF\s+NOT\s+public\.has_store_access_as/is.test(def)) {
    issues.push({ severity: 'HIGH', rule: 'VULNERABLE_PATTERN_IS_NOT_NULL_THEN', msg: 'Patrón vulnerable fail-open: IS NOT NULL THEN IF NOT has_store_access_as' });
  }
  // ─── Check 3: anon EXECUTE (identical rule; Layer A: captured proacl, Layer B: replayed GRANT/REVOKE) ───
  if (aclAnonFlag) {
    const isWebhook = /webhook|public_endpoint|register_anon/i.test(name);
    if (!isWebhook) {
      issues.push({ severity: 'MEDIUM', rule: 'ANON_EXECUTE_GRANTED', msg: 'anon tiene EXECUTE en función SECURITY DEFINER de negocio' });
    }
  }
  // ─── Check 4: SET search_path explicit (identical to LIVE) ───
  if (!/SET search_path/i.test(def)) {
    issues.push({ severity: 'LOW', rule: 'SEARCH_PATH_NOT_SET', msg: 'Función SECURITY DEFINER sin SET search_path explícito (vulnerable a search_path injection)' });
  }
  return issues;
}

// ────────────────────── SQL scanning helpers (Layer B) ──────────────────────
function stripComments(sql) {
  let out = '';
  let i = 0;
  const n = sql.length;
  while (i < n) {
    const ch = sql[i];
    if (ch === '$') {
      const m = /^\$[A-Za-z0-9_]*\$/.exec(sql.slice(i));
      if (m) {
        const tag = m[0];
        const end = sql.indexOf(tag, i + tag.length);
        const stop = end === -1 ? n : end + tag.length;
        out += sql.slice(i, stop);
        i = stop;
        continue;
      }
    }
    if (ch === "'") {
      let j = i + 1;
      while (j < n) {
        if (sql[j] === "'" && sql[j + 1] === "'") { j += 2; continue; }
        if (sql[j] === "'") { j++; break; }
        j++;
      }
      out += sql.slice(i, j);
      i = j;
      continue;
    }
    if (ch === '-' && sql[i + 1] === '-') {
      while (i < n && sql[i] !== '\n') i++;
      continue;
    }
    if (ch === '/' && sql[i + 1] === '*') {
      let depth = 1; i += 2;
      while (i < n && depth > 0) {
        if (sql[i] === '/' && sql[i + 1] === '*') { depth++; i += 2; continue; }
        if (sql[i] === '*' && sql[i + 1] === '/') { depth--; i += 2; continue; }
        i++;
      }
      out += ' ';
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

function extractFunctions(cleanText, sourceFile) {
  const defs = [];
  const re = /create\s+(?:or\s+replace\s+)?function\s+((?:[A-Za-z_][\w$]*)\.)?([A-Za-z_][\w$]*)\s*\(/gi;
  let guard = 0;
  let idx = 0;
  while (guard++ < 5000) {
    const m = re.exec(cleanText.slice(idx));
    if (!m) break;
    const start = idx + m.index;
    const parenOpen = start + m[0].length - 1;
    let depth = 0, j = parenOpen, inStr = null;
    for (; j < cleanText.length; j++) {
      const c = cleanText[j];
      if (inStr) { if (c === inStr) inStr = null; continue; }
      if (c === "'") { inStr = c; continue; }
      if (c === '$') { const d = /^\$[A-Za-z0-9_]*\$/.exec(cleanText.slice(j)); if (d) { const e = cleanText.indexOf(d[0], j + d[0].length); if (e !== -1) { j = e + d[0].length - 1; continue; } } }
      if (c === '(') depth++;
      if (c === ')') { depth--; if (depth === 0) break; }
    }
    const headerArgs = cleanText.slice(parenOpen + 1, j);
    const rest = cleanText.slice(j + 1, j + 1 + 200000);
    const asM = /\bas\b((?:\s|\S)*?)((\$[A-Za-z0-9_]*\$)|')/i.exec(rest);
    if (!asM) { idx = start + m[0].length; continue; }
    const header = rest.slice(0, asM.index);
    const bodyStart = j + 1 + asM.index + asM[1].length;
    let bodyText, bodyEnd;
    if (asM[3] && asM[3].startsWith('$')) {
      const end = cleanText.indexOf(asM[3], bodyStart + asM[3].length);
      if (end === -1) { idx = start + m[0].length; continue; }
      bodyText = cleanText.slice(bodyStart + asM[3].length, end);
      bodyEnd = end + asM[3].length;
    } else {
      let k = bodyStart + 1;
      while (k < cleanText.length) {
        if (cleanText[k] === "'" && cleanText[k + 1] === "'") { k += 2; continue; }
        if (cleanText[k] === "'") break;
        k++;
      }
      bodyText = cleanText.slice(bodyStart + 1, k);
      bodyEnd = k + 1;
    }
    defs.push({
      file: sourceFile,
      schema: (m[1] || 'public.').replace(/\.$/, '').toLowerCase(),
      name: m[2].toLowerCase(),
      header,
      body: bodyText,
      text: cleanText.slice(start, bodyEnd),
      argsRaw: headerArgs,
    });
    idx = bodyEnd;
  }
  return defs;
}

function replayAnonAcl(cleanText, state, sourceFile) {
  const re = /(grant|revoke)\s+execute\s+on\s+function\s+((?:[A-Za-z_][\w$]*\.)?[A-Za-z_][\w$]*)[^;]*?\bto\s+((?:[A-Za-z_][\w$]*\s*,\s*)*[A-Za-z_][\w$]*)[^;]*;/gi;
  let m;
  while ((m = re.exec(cleanText))) {
    const verb = m[1].toLowerCase();
    const fn = m[2].split('.').pop().toLowerCase();
    const roles = m[3].split(',').map(s => s.trim().toLowerCase());
    if (!state[fn]) state[fn] = { grants: [], file: sourceFile };
    for (const r of roles) if (r === 'anon') state[fn].grants.push(verb === 'grant');
  }
}

function countArgs(argsRaw) {
  const s = (argsRaw || '').trim();
  if (!s) return 0;
  let depth = 0, count = 1, inStr = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === "'") inStr = !inStr;
    if (inStr) continue;
    if (c === '(' || c === '[') depth++;
    if (c === ')' || c === ']') depth--;
    if (c === ',' && depth === 0) count++;
  }
  return count;
}

function loadBaseline() {
  let baseline = [];
  if (fs.existsSync(ALLOWLIST_FILE)) {
    const al = JSON.parse(fs.readFileSync(ALLOWLIST_FILE, 'utf8'));
    baseline = al.security_contract_static_baseline || [];
  }
  const now = new Date();
  const valid = new Map();
  for (const item of baseline) {
    if (item.expires && new Date(item.expires) < now) continue; // expired entries are ignored (= violations block again)
    valid.set(item.function, item);
  }
  return valid;
}

// ────────────────────────────── main ─────────────────────────────────────
(async () => {
  try {
    console.log('═'.repeat(80));
    console.log('🔒 TEST DE CONTRATO (estático, CI-safe) — Seguridad de funciones SECURITY DEFINER');
    console.log('═'.repeat(80));

    const blocking = [];
    let warnings = 0;

    // ═══════════ Layer A — certified LIVE surface ═══════════
    if (!fs.existsSync(SURFACE_FILE)) {
      console.error('❌ Falta supabase/security-contract/contract-surface.sql — regenerar con scripts/export-contract-surface.cjs (nunca en CI)');
      process.exit(2);
    }
    const surfaceRaw = fs.readFileSync(SURFACE_FILE, 'utf8');
    const surfaceSha = crypto.createHash('sha256').update(surfaceRaw).digest('hex');
    const blocks = surfaceRaw.split(/^-- @contract-function /m).slice(1);
    const layerAViolations = [];
    let layerAChecked = 0;
    let pinA = false;
    for (const b of blocks) {
      const metaM = /^name=(\S+) args="([^"]*)" proacl=(\[[^\n]*\])\n/.exec(b);
      if (!metaM) { console.error('❌ bloque @contract-function corrupto (sin metadatos)'); process.exit(2); }
      const name = metaM[1].toLowerCase();
      const proacl = JSON.parse(metaM[3]);
      const defText = b.slice(metaM[0].length).trimEnd();
      layerAChecked++;
      if (name === 'receive_purchase') pinA = true;
      const anonFlag = proacl.some(a => a.startsWith('anon='));
      const issues = checkFunction(defText, name, anonFlag);
      if (issues.length > 0) layerAViolations.push({ function_name: name, args: metaM[2], issues });
    }
    if (pinA) {
      layerAViolations.push({
        function_name: 'receive_purchase', args: '(p_purchase_id uuid)',
        issues: [{ severity: 'CRITICAL', rule: 'RETIRED_V1_FUNCTION_REINTRODUCED', msg: 'receive_purchase(uuid) fue retirada (REM-INV-2R) pero aparece en el surface certificado' }],
      });
    }

    console.log(`\n── Capa A — surface LIVE certificado (${path.basename(SURFACE_FILE)} sha256=${surfaceSha.slice(0, 12)}…)`);
    console.log(`Funciones SECURITY DEFINER con escritura detectadas: ${layerAChecked}`);
    console.log(`Funciones verificadas: ${layerAChecked}`);
    console.log(`Funciones con violaciones: ${layerAViolations.length}`);
    if (pinA) console.log('🚨 PIN REM-INV-2R: receive_purchase(uuid) REINTRODUCIDA — BUILD BLOQUEADO');
    else console.log('✅ PIN REM-INV-2R: receive_purchase(uuid) ausente del surface certificado');
    for (const v of layerAViolations) {
      console.log(`\n▸ [Capa A] ${v.function_name}(${v.args})`);
      v.issues.forEach(issue => {
        const icon = issue.severity === 'CRITICAL' ? '🚨' : issue.severity === 'HIGH' ? '🔴' : issue.severity === 'MEDIUM' ? '🟠' : '🟡';
        console.log(`  ${icon} [${issue.severity}] ${issue.rule}`);
        console.log(`     ${issue.msg}`);
      });
      if (v.issues.some(i => i.severity === 'CRITICAL' || i.severity === 'HIGH')) blocking.push(v);
      warnings += v.issues.filter(i => i.severity === 'MEDIUM' || i.severity === 'LOW').length;
    }

    // ═══════════ Layer B — migration stream (PR surface) ═══════════
    const files = fs.readdirSync(MIGRATIONS_DIR).filter(f => f.endsWith('.sql')).sort();
    const finalDefs = new Map();
    const anonAcl = {};
    for (const f of files) {
      const clean = stripComments(fs.readFileSync(path.join(MIGRATIONS_DIR, f), 'utf8'));
      for (const d of extractFunctions(clean, f)) {
        const key = `${d.schema}.${d.name}/${countArgs(d.argsRaw)}`;
        finalDefs.set(key, { ...d, secdef: /security\s+definer/i.test(d.header), key });
      }
      replayAnonAcl(clean, anonAcl, f);
    }
    const writeFns = [...finalDefs.values()].filter(d => d.secdef && WRITE_RE.test(d.text))
      .sort((a, b) => (a.name + a.key).localeCompare(b.name + b.key));

    const baseline = loadBaseline();
    const layerBKnown = [];
    const layerBNew = [];
    let pinB = false;
    for (const f of writeFns) {
      if (f.schema === 'public' && f.name === 'receive_purchase') pinB = true;
      const anonState = anonAcl[f.name];
      const anonFlag = !!anonState && anonState.grants.length > 0 && anonState.grants[anonState.grants.length - 1] === true;
      const issues = checkFunction(f.text, f.name, anonFlag);
      if (issues.length === 0) continue;
      const shortKey = `${f.name}/${countArgs(f.argsRaw)}`;
      const entry = baseline.get(shortKey) || baseline.get(f.name);
      if (entry) {
        // actual rules must be a SUBSET of the reviewed baseline rules; a new rule = new violation
        const newRules = issues.filter(i => !entry.rules.includes(i.rule));
        if (newRules.length === 0) { layerBKnown.push({ f, shortKey, issues }); continue; }
        layerBNew.push({ f, shortKey, issues: newRules, why: 'regla nueva sobre función con baseline' });
      } else {
        layerBNew.push({ f, shortKey, issues, why: 'violación sin baseline' });
      }
    }

    console.log(`\n── Capa B — stream de migraciones (superficie PR): ${files.length} archivos, ${writeFns.length} funciones SECDEF-write`);
    console.log(`Funciones verificadas: ${writeFns.length}`);
    console.log(`Violaciones históricas dentro del baseline revisado: ${layerBKnown.length}`);
    console.log(`Violaciones NUEVAS (bloqueantes): ${layerBNew.length}`);
    if (pinB) console.log('🚨 PIN REM-INV-2R: receive_purchase(uuid) REINTRODUCIDA en migraciones — BUILD BLOQUEADO');
    else console.log('✅ PIN REM-INV-2R: receive_purchase(uuid) ausente del stream de migraciones');
    for (const v of layerBKnown) {
      console.log(`  ⚪ baseline: ${v.shortKey} → [${v.issues.map(i => i.rule).join(', ')}]`);
    }
    for (const v of layerBNew) {
      console.log(`\n▸ [Capa B] ${v.f.name}(${v.shortKey}) — ${v.why}`);
      v.issues.forEach(issue => {
        const icon = issue.severity === 'CRITICAL' ? '🚨' : issue.severity === 'HIGH' ? '🔴' : issue.severity === 'MEDIUM' ? '🟠' : '🟡';
        console.log(`  ${icon} [${issue.severity}] ${issue.rule}`);
        console.log(`     ${issue.msg}`);
      });
      if (v.issues.some(i => i.severity === 'CRITICAL' || i.severity === 'HIGH')) blocking.push(v);
      warnings += v.issues.filter(i => i.severity === 'MEDIUM' || i.severity === 'LOW').length;
    }

    // Optional state export (used by REM-INV-5 fidelity validation; no-op in CI)
    if (process.env.SC_STATIC_EXPORT) {
      const dump = writeFns.map(f => ({ schema: f.schema, name: f.name, argcount: countArgs(f.argsRaw), key: f.key, file: f.file }));
      fs.writeFileSync(process.env.SC_STATIC_EXPORT, JSON.stringify({ functions: dump, migrations: files.length, layerAChecked }, null, 2));
    }

    console.log('\n' + '═'.repeat(80));
    if (blocking.length === 0) {
      if (warnings > 0) {
        console.log(`⚠️ CONTRATO OK con ${warnings} warning(s) MEDIUM/LOW (semántica idéntica al contract LIVE)`);
      } else {
        console.log(`🎉 CONTRATO OK — Capa A: ${layerAChecked}/${layerAChecked} · Capa B: ${writeFns.length} verificadas, ${layerBKnown.length} baseline, ${layerBNew.length} nuevas`);
      }
      console.log('═'.repeat(80));
      process.exit(0);
    }
    console.log(`🚨 VIOLACIONES BLOQUEANTES: ${blocking.length} — BUILD BLOQUEADO`);
    console.log('═'.repeat(80));
    process.exit(1);
  } catch (err) {
    console.error('❌ Error ejecutando test de contrato estático:', err);
    process.exit(2);
  }
})();
